// Contact matching, repeat detection, and the contact, note, opportunity and task bodies written to GoHighLevel (SPEC §3.3–§4).

const TIER_RANK = { not_qualified: 0, needs_review: 1, qualified: 2 };
// The custom fields this workflow owns; ids are resolved by ghl_setup.py into output/ghl-ids.json.
const FIELD_KEYS = ['lead_tier', 'inquiry_topic', 'inquiry_urgency', 'inquiry_source', 'ai_reason', 'inquiry_source_ids'];
const STAGES = { qualified: 'New – qualified', needs_review: 'Needs review' };
const SOURCE_LABEL = { form: 'Website form', email: 'Email', meta_lead: 'Facebook lead form' };
const TAG = 'ai-intake';

// Email first, then phone; each is one duplicate-search call.
function lookupRequests(inquiry, locationId) {
  const query = (key, value) => `/contacts/search/duplicate?locationId=${encodeURIComponent(locationId)}&${key}=${encodeURIComponent(value)}`;
  const requests = [];
  if (inquiry.email) requests.push({ by: 'email', path: query('email', inquiry.email) });
  if (inquiry.phone) requests.push({ by: 'phone', path: query('number', inquiry.phone) });
  return requests;
}

// Input: [{ by, statusCode, body }] in lookup order (HTTP node with fullResponse + neverError).
function resolveLookups(responses) {
  for (const response of responses) {
    if (!response || response.statusCode !== 200) {
      // A failed search must not look like "no match": stop so the error workflow alerts.
      throw new Error(`GoHighLevel lookup by ${response && response.by} failed: ${response ? response.statusCode : 'no response'} ${JSON.stringify(response && response.body).slice(0, 300)}`);
    }
  }
  for (const response of responses) {
    const contact = response.body && response.body.contact;
    if (contact && contact.id) return { contactId: contact.id, matchedBy: response.by };
  }
  return { contactId: null, matchedBy: null };
}

function fieldValue(contact, fieldId) {
  const list = contact.customFields || contact.customField || [];
  const found = list.find((item) => item.id === fieldId);
  if (!found) return null;
  const value = found.value !== undefined ? found.value : found.field_value;
  return value === undefined || value === '' ? null : value;
}

// GET /contacts/{id} → the parts this workflow reads back.
function readContact(response, ids) {
  if (!response || response.statusCode !== 200 || !response.body || !response.body.contact) {
    throw new Error(`GoHighLevel get contact failed: ${response ? response.statusCode : 'no response'} ${JSON.stringify(response && response.body).slice(0, 300)}`);
  }
  const contact = response.body.contact;
  const sourceIds = String(fieldValue(contact, ids.fields.inquiry_source_ids) || '').split('\n').map((item) => item.trim()).filter(Boolean);
  return {
    id: contact.id,
    firstName: contact.firstName || null,
    lastName: contact.lastName || null,
    email: contact.email || null,
    phone: contact.phone || null,
    companyName: contact.companyName || null,
    tier: fieldValue(contact, ids.fields.lead_tier),
    sourceIds,
  };
}

function isRepeat(contact, sourceId) {
  return Boolean(contact) && contact.sourceIds.includes(sourceId);
}

function mergeTier(existing, incoming) {
  if (!existing || !(existing in TIER_RANK)) return incoming;
  return existing === 'qualified' ? 'qualified' : incoming;
}

function splitName(name) {
  const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
  return { first: parts[0] || '', last: parts.slice(1).join(' ') };
}

function customFields(ids, values) {
  return Object.entries(values).map(([key, value]) => ({ id: ids.fields[key], field_value: value }));
}

// Create (POST /contacts/) or update (PUT /contacts/{id}). Existing contacts keep their identity; only empty fields are filled.
// PUT replaces tags, so tags are only sent on create.
function contactRequest(inquiry, qualification, contact, ids, locationId) {
  const name = splitName(inquiry.name);
  const tier = mergeTier(contact && contact.tier, qualification.tier);
  const sourceIds = [...((contact && contact.sourceIds) || []), inquiry.source_id];
  const fields = customFields(ids, {
    lead_tier: tier,
    inquiry_topic: qualification.topic,
    inquiry_urgency: qualification.urgency,
    inquiry_source: inquiry.source,
    ai_reason: qualification.reason,
    inquiry_source_ids: sourceIds.join('\n'),
  });
  if (!contact) {
    const body = { locationId, source: SOURCE_LABEL[inquiry.source] || inquiry.source, tags: [TAG], customFields: fields };
    if (name.first) body.firstName = name.first;
    if (name.last) body.lastName = name.last;
    if (inquiry.email) body.email = inquiry.email;
    if (inquiry.phone) body.phone = inquiry.phone;
    if (inquiry.company) body.companyName = inquiry.company;
    return { method: 'POST', path: '/contacts/', body, tier };
  }
  const body = { customFields: fields };
  if (name.first && !contact.firstName) body.firstName = name.first;
  if (name.last && !contact.lastName) body.lastName = name.last;
  if (inquiry.email && !contact.email) body.email = inquiry.email;
  if (inquiry.phone && !contact.phone) body.phone = inquiry.phone;
  if (inquiry.company && !contact.companyName) body.companyName = inquiry.company;
  return { method: 'PUT', path: `/contacts/${contact.id}`, body, tier };
}

// With "Allow Duplicate Contact" off, a create that collides with an existing contact is refused and names it.
function parseDuplicateCreate(response) {
  if (!response || response.statusCode !== 400 || !response.body) return null;
  const body = response.body;
  const meta = body.meta || {};
  const id = meta.contactId || meta.contact_id || (meta.contact && meta.contact.id) || body.contactId || null;
  return /duplicat/i.test(String(body.message || '')) && id ? id : null;
}

function createdContactId(response) {
  if (!response || ![200, 201].includes(response.statusCode)) return null;
  const contact = response.body && (response.body.contact || response.body);
  return contact && contact.id ? contact.id : null;
}

function oneLine(text, limit) {
  const flat = String(text ?? '').replace(/\s+/g, ' ').trim();
  return flat.length <= limit ? flat : `${flat.slice(0, limit - 1).trimEnd()}…`;
}

function inquiryNote(inquiry, qualification) {
  const header = [`Inquiry via ${SOURCE_LABEL[inquiry.source] || inquiry.source} at ${inquiry.received_at}`, ...(inquiry.subject ? [inquiry.subject] : [])];
  const ai = `AI: ${qualification.tier} / ${qualification.topic} / ${qualification.urgency} — ${qualification.reason}`;
  return { body: [...header, '', inquiry.message, '', ai, '', `Source id: ${inquiry.source_id}`].join('\n') };
}

function decisionNote(result, { date, sentTo }) {
  if (result.timedOut) return { body: 'AI reply review timed out. Reply drafted by AI; nothing sent.' };
  if (result.decision === 'approve') {
    return { body: `AI reply approved by ${result.reviewer}\nReply drafted by AI, edited: ${result.edited ? 'yes' : 'no'}, approved on ${date}, sent to ${sentTo}.\n\nSubject: ${result.subject}\n\n${result.body}` };
  }
  return { body: `AI reply rejected by ${result.reviewer}\nReply drafted by AI, rejected on ${date}, nothing sent.` };
}

function stageRank(stageId, ids) {
  if (stageId === ids.stages[STAGES.qualified]) return 2;
  if (stageId === ids.stages[STAGES.needs_review]) return 1;
  return null; // Contacted, Won, Lost or unknown: a person already owns it.
}

// One open opportunity per contact in the Inquiries pipeline; it only moves up, and never once it's past the two intake stages.
function planOpportunity({ tier, contactId, label, topic, existing, ids, locationId }) {
  const target = STAGES[tier];
  const targetId = target ? ids.stages[target] : null;
  if (!existing) {
    if (!targetId) return { request: null, stage: null, opportunityId: null, needsTask: false };
    const body = { pipelineId: ids.pipelineId, locationId, name: oneLine(`${label} – ${topic}`, 120), pipelineStageId: targetId, status: 'open', contactId, source: 'AI lead intake' };
    return { request: { method: 'POST', path: '/opportunities/', body }, stage: target, opportunityId: null, needsTask: tier === 'qualified' };
  }
  const current = stageRank(existing.pipelineStageId, ids);
  const currentName = Object.keys(ids.stages).find((name) => ids.stages[name] === existing.pipelineStageId) || null;
  if (current === null || !targetId || stageRank(targetId, ids) <= current) {
    return { request: null, stage: currentName, opportunityId: existing.id, needsTask: false };
  }
  return { request: { method: 'PUT', path: `/opportunities/${existing.id}`, body: { pipelineId: ids.pipelineId, pipelineStageId: targetId } }, stage: target, opportunityId: existing.id, needsTask: tier === 'qualified' };
}

function readOpenOpportunity(response, ids) {
  if (!response || response.statusCode !== 200) {
    throw new Error(`GoHighLevel opportunity search failed: ${response ? response.statusCode : 'no response'} ${JSON.stringify(response && response.body).slice(0, 300)}`);
  }
  const list = (response.body && response.body.opportunities) || [];
  return list.find((item) => item.pipelineId === ids.pipelineId && (item.status || 'open') === 'open') || null;
}

// Offset of a time zone at a given instant, in minutes (Intl only, no libraries).
function tzOffsetMinutes(date, timeZone) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' })
    .formatToParts(date).filter((part) => part.type !== 'literal').map((part) => [part.type, Number(part.value)]));
  return (Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second) - date.getTime()) / 60000;
}

// Next business day at 10:00 in the location's time zone.
function nextBusinessDay10(nowIso, timeZone = 'America/Los_Angeles') {
  const now = new Date(nowIso);
  const local = new Date(now.getTime() + tzOffsetMinutes(now, timeZone) * 60000);
  const day = new Date(Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate() + 1, 10, 0, 0));
  while ([0, 6].includes(day.getUTCDay())) day.setUTCDate(day.getUTCDate() + 1);
  return new Date(day.getTime() - tzOffsetMinutes(day, timeZone) * 60000).toISOString();
}

function followUpTask(inquiry, qualification, { now, timeZone }) {
  const who = inquiry.name || inquiry.email || inquiry.phone;
  return {
    title: oneLine(`Call ${who} about ${qualification.topic.replace(/_/g, ' ')}`, 120),
    body: `Qualified by AI (${qualification.urgency} urgency): ${qualification.reason}\nCheck the inquiry note before calling.`,
    dueDate: nextBusinessDay10(now, timeZone),
    completed: false,
  };
}

function contactUrl(locationId, contactId) {
  return `https://app.gohighlevel.com/v2/location/${locationId}/contacts/detail/${contactId}`;
}

const ctx = $input.first().json;
const r = ctx.result;
const date = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Taipei' });
const approved = !r.timedOut && r.decision === 'approve';
const sentTo = approved ? ctx.email.to : null;
const draft = r.timedOut ? 'timeout' : approved ? 'approved' : 'rejected';
const runLog = { inquiry: ctx.inquiry, contactId: ctx.contactId, matchedBy: ctx.matchedBy, opportunityId: ctx.opportunityId, stage: ctx.stage, taskId: ctx.taskId, action: ctx.action, qualification: ctx.qualification, draft, sentTo, reviewer: r.reviewer || null, edited: r.timedOut ? null : r.edited, alerts: [] };
return [{ json: { contactId: ctx.contactId, note: decisionNote(r, { date, sentTo }), runLog } }];

const res = $input.first().json;
if (![200, 201].includes(res.statusCode)) throw new Error('GoHighLevel add decision note failed: ' + res.statusCode + ' ' + JSON.stringify(res.body).slice(0, 300));
return [{ json: { runLog: $('Prepare decision note').first().json.runLog } }];

// Human approval: review page, decision parsing and the outgoing reply (SPEC §6).

function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function safeId(sourceId) {
  return String(sourceId || 'unknown').replace(/[^A-Za-z0-9._-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
}

const TIER_LABEL = { qualified: 'Qualified', needs_review: 'Needs review', not_qualified: 'Not qualified' };

function buildReviewPage({ inquiry, qualification, draft, recordUrl, resumeUrl }) {
  const row = (label, value) => `<tr><th>${escapeHtml(label)}</th><td>${escapeHtml(value)}</td></tr>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Reply review: ${escapeHtml(inquiry.name || inquiry.email || 'new lead')}</title>
<style>body{font:16px/1.5 system-ui,sans-serif;max-width:860px;margin:2rem auto;padding:0 16px;background:#f4f6f8;color:#1d2430}
section{background:#fff;border-radius:10px;padding:1rem 1.25rem;margin:1rem 0;box-shadow:0 1px 2px #0001}
h1{font-size:1.4rem}h2{font-size:1.05rem;margin:.2rem 0 .8rem}th{text-align:left;color:#5b6575;font-weight:600;padding:.2rem 1rem .2rem 0;vertical-align:top;white-space:nowrap}
.msg{white-space:pre-wrap;background:#f7f8fa;border-radius:6px;padding:.75rem}.tier{display:inline-block;border-radius:999px;padding:.1rem .6rem;background:#e7f0ff;color:#1747a6;font-weight:600}
label{display:block;margin:.8rem 0 .3rem;font-weight:600}input[type=text],textarea{width:100%;box-sizing:border-box;font:inherit;padding:.5rem;border:1px solid #c9cfd8;border-radius:6px}
textarea{min-height:12rem}.choices label{display:inline-block;font-weight:500;margin-right:1.5rem}button{font:inherit;font-weight:600;background:#1d4ed8;color:#fff;border:0;border-radius:6px;padding:.6rem 1.2rem;cursor:pointer}
.note{color:#5b6575;font-size:.9rem}</style></head><body>
<h1>Review the AI draft before anything is sent</h1>
<section><h2>Inquiry</h2><table>
${row('From', `${inquiry.name || '(no name)'} <${inquiry.email || 'no email'}>`)}
${row('Phone', inquiry.phone || '(not given)')}
${row('Company', inquiry.company || '(not given)')}
${row('Source', `${inquiry.source} · ${inquiry.received_at}`)}
${row('Subject', inquiry.subject || '(none)')}
</table><p class="msg">${escapeHtml(inquiry.message)}</p>
<p><a href="${escapeHtml(recordUrl)}">Open contact in GoHighLevel</a></p></section>
<section><h2>AI classification</h2><p><span class="tier">${escapeHtml(TIER_LABEL[qualification.tier] || qualification.tier)}</span> · ${escapeHtml(qualification.topic)} · urgency ${escapeHtml(qualification.urgency)}</p><p>${escapeHtml(qualification.reason)}</p></section>
<section><h2>Draft reply</h2><form method="POST" action="${escapeHtml(resumeUrl)}" enctype="application/x-www-form-urlencoded">
<label for="subject">Subject</label><input type="text" id="subject" name="subject" value="${escapeHtml(draft.subject)}">
<label for="body">Message</label><textarea id="body" name="body">${escapeHtml(draft.body)}</textarea>
<label>Decision</label><div class="choices"><label><input type="radio" name="decision" value="approve"> Approve and send</label><label><input type="radio" name="decision" value="reject"> Reject, send nothing</label></div>
<label for="reviewer">Your name</label><input type="text" id="reviewer" name="reviewer" required>
<p class="note">Nothing is sent until you approve. Your name is saved on the GoHighLevel contact with the decision.</p>
<button type="submit">Submit review</button></form></section></body></html>`;
}

function parseDecision(body, draft) {
  if (body == null) return { timedOut: true, errors: [] };
  const errors = [];
  const reviewer = String(body.reviewer || '').trim();
  const decision = String(body.decision || '').trim();
  if (!reviewer) errors.push('Your name is required');
  if (!['approve', 'reject'].includes(decision)) errors.push('Choose Approve or Reject');
  const subject = String(body.subject ?? draft.subject).trim();
  const text = String(body.body ?? draft.body).replace(/\r\n/g, '\n').trim();
  if (decision === 'approve' && (!subject || !text)) errors.push('Subject and message cannot be empty');
  const edited = subject !== String(draft.subject).trim() || text !== String(draft.body).replace(/\r\n/g, '\n').trim();
  return { timedOut: false, errors, reviewer, decision, subject, body: text, edited };
}

function outgoingEmail({ to, subject, body, demoMode, redirectTo }) {
  if (demoMode) {
    if (!redirectTo) throw new Error('DEMO_MODE=1 needs REPLY_REDIRECT_TO; refusing to email a demo address');
    return { to: redirectTo, subject: `[demo → ${to}] ${subject}`, body };
  }
  return { to, subject, body };
}

function errorPage(errors) {
  return `<!doctype html><html><head><meta charset="utf-8"><title>Review not accepted</title></head><body style="font:16px system-ui;max-width:640px;margin:3rem auto"><h1>Review not accepted</h1><ul>${errors.map((error) => `<li>${escapeHtml(error)}</li>`).join('')}</ul><p>Go back, fix the form and submit again. Nothing was sent.</p></body></html>`;
}

function receiptPage(text) {
  return `<!doctype html><html><head><meta charset="utf-8"><title>Review received</title></head><body style="font:16px system-ui;max-width:640px;margin:3rem auto"><h1>${escapeHtml(text)}</h1></body></html>`;
}

// Slack texts and the run log; every number here comes from code, not the AI.

function maskSecrets(value) {
  return String(value ?? '')
    .replace(/Bearer\s+[^\s"']+/gi, 'Bearer ***')
    .replace(/\bsk-[A-Za-z0-9_-]+/g, '***')
    .replace(/\bpit-[A-Za-z0-9-]+/g, '***')
    .replace(/\bEAA[A-Za-z0-9]{20,}/g, '***')
    .replace(/access_token=[^&\s"']+/g, 'access_token=***')
    .replace(/https:\/\/hooks\.slack\.com\/[^\s"']+/g, 'https://hooks.slack.com/***');
}

function formatAlert(payload = {}, baseUrl = 'http://localhost:5681') {
  const workflow = payload.workflow || {};
  const execution = payload.execution || {};
  const message = maskSecrets((execution.error && execution.error.message) || 'Unknown error');
  const url = `${baseUrl}/workflow/${workflow.id || ''}/executions/${execution.id || ''}`;
  return { text: `:rotating_light: Lead intake workflow error\nWorkflow: ${workflow.name || workflow.id || 'unknown'}\nNode: ${execution.lastNodeExecuted || 'unknown'}\nError: ${message}\n${url}`, url };
}

function rejectedInputAlert(inquiry, reason) {
  const who = inquiry.email || inquiry.phone || inquiry.name || 'unknown sender';
  return `:warning: Inquiry not accepted (${reason}) from ${who} via ${inquiry.source}. Nothing was written to GoHighLevel; please follow up by hand if needed.`;
}

function llmFailureAlert(inquiry, qualification, link) {
  return `:warning: AI classification failed for ${inquiry.email || inquiry.phone} (${qualification.llm_error}). The lead was saved in GoHighLevel as Needs review with no draft reply: ${link}`;
}

function reviewAlert(inquiry, qualification, reviewUrl) {
  return `:incoming_envelope: New lead: ${inquiry.name || inquiry.email} (${qualification.tier}, ${qualification.urgency} urgency) — review the draft reply: ${reviewUrl}`;
}

function signatureAlert(reason) {
  return `:no_entry: A request to the Facebook lead webhook was refused (${reason}). Nothing was written. If this repeats, check META_APP_SECRET and who is calling the webhook.`;
}

function buildRunLog({ inquiry, fixtureId = null, contactId = null, matchedBy = null, action, qualification = null, opportunityId = null, stage = null, taskId = null, draft = 'none', sentTo = null, reviewer = null, edited = null, alerts = [], executionId = null }) {
  return {
    ts: new Date().toISOString(),
    execution_id: executionId,
    source_id: inquiry.source_id,
    source: inquiry.source,
    fixture_id: fixtureId,
    email: inquiry.email,
    contact_id: contactId,
    matched_by: matchedBy,
    action,
    tier: qualification ? qualification.tier : null,
    llm_ok: qualification ? qualification.llm_ok : null,
    llm_error: qualification ? qualification.llm_error : null,
    opportunity_id: opportunityId,
    stage,
    task_id: taskId,
    draft,
    reviewer,
    edited,
    sent_to: sentTo,
    alerts: alerts.map(maskSecrets),
  };
}

// OpenAI requests and the checks that decide whether an AI answer can be used (SPEC §5).

const TIERS = ['qualified', 'needs_review', 'not_qualified'];
const TOPICS = ['regular_cleaning', 'deep_cleaning', 'quote_request', 'complaint', 'job_application', 'sales_pitch', 'other'];
const URGENCIES = ['high', 'normal', 'low'];
const BROKEN_MODEL = 'does-not-exist-model';

function fillTemplate(template, values) {
  return String(template).replace(/\{\{(\w+)\}\}/g, (_, key) => (values[key] == null ? '' : String(values[key])));
}

function inquiryText(inquiry) {
  return [
    `Source: ${inquiry.source}`,
    `Name: ${inquiry.name || '(not given)'}`,
    `Company: ${inquiry.company || '(not given)'}`,
    `Subject: ${inquiry.subject || '(none)'}`,
    'Message:',
    inquiry.message,
  ].join('\n');
}

function chatRequest(prompt, userContent, schemaName, modelOverride) {
  const request = {
    messages: [{ role: 'system', content: prompt.system }, { role: 'user', content: userContent }],
    response_format: { type: 'json_schema', json_schema: { name: schemaName, strict: true, schema: prompt.schema } },
    temperature: 0,
  };
  if (modelOverride) request.model = modelOverride;
  return request;
}

function buildQualifyRequest(inquiry, prompt) {
  const override = inquiry.demo_flags && inquiry.demo_flags.break_llm ? BROKEN_MODEL : undefined;
  return chatRequest(prompt, fillTemplate(prompt.userTemplate, { inquiry: inquiryText(inquiry) }), 'lead_qualification', override);
}

function buildDraftRequest(inquiry, qualification, prompt) {
  const content = fillTemplate(prompt.userTemplate, { inquiry: inquiryText(inquiry), tier: qualification.tier, topic: qualification.topic, urgency: qualification.urgency });
  return chatRequest(prompt, content, 'reply_draft');
}

function readLlmJson(response) {
  if (!response) return { data: null, error: 'empty_response' };
  if (response.error) {
    const error = response.error;
    const status = error.httpCode || error.status || (error.cause && error.cause.status) || '';
    return { data: null, error: `api_error${status ? `_${status}` : ''}` };
  }
  const content = response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content;
  if (!content) return { data: null, error: 'empty_response' };
  try {
    return { data: JSON.parse(content), error: null };
  } catch (e) {
    return { data: null, error: 'invalid_json' };
  }
}

const squash = (text) => String(text || '').replace(/\s+/g, ' ').trim().toLowerCase();

function validateQualification(data, message) {
  const errors = [];
  if (!data || typeof data !== 'object') return { valid: false, errors: ['not_an_object'] };
  if (!TIERS.includes(data.tier)) errors.push('bad_tier');
  if (!TOPICS.includes(data.topic)) errors.push('bad_topic');
  if (!URGENCIES.includes(data.urgency)) errors.push('bad_urgency');
  if (!String(data.reason || '').trim()) errors.push('missing_reason');
  const quote = squash(data.quote);
  if (!quote || !squash(message).includes(quote)) errors.push('quote_not_in_message');
  return { valid: errors.length === 0, errors };
}

// A verbatim quote that runs long is cut at a word boundary; it stays a prefix of the original text.
const QUOTE_LIMIT = 160;
function shortenQuote(quote) {
  const text = String(quote).replace(/\s+/g, ' ').trim();
  if (text.length <= QUOTE_LIMIT) return text;
  const cut = text.slice(0, QUOTE_LIMIT);
  return `${cut.slice(0, cut.lastIndexOf(' ') > 40 ? cut.lastIndexOf(' ') : QUOTE_LIMIT).replace(/[\s,;:.]+$/, '')}…`;
}

function qualificationFromLlm(response, message) {
  const parsed = readLlmJson(response);
  if (parsed.error) return fallbackQualification(parsed.error);
  const checked = validateQualification(parsed.data, message);
  if (!checked.valid) return fallbackQualification(`validation_failed:${checked.errors.join(',')}`);
  const { tier, topic, urgency, reason, quote } = parsed.data;
  return { tier, topic, urgency, reason: `${reason.trim()} Quote: "${shortenQuote(quote)}"`, llm_ok: true, llm_error: null };
}

function fallbackQualification(errorClass) {
  return {
    tier: 'needs_review',
    topic: 'other',
    urgency: 'normal',
    reason: `AI classification failed: ${errorClass}; needs a human look.`,
    llm_ok: false,
    llm_error: errorClass,
  };
}

function draftFromLlm(response) {
  const parsed = readLlmJson(response);
  if (parsed.error) return { ok: false, error: parsed.error };
  const { subject, body } = parsed.data || {};
  const words = String(body || '').trim().split(/\s+/).filter(Boolean).length;
  if (!String(subject || '').trim() || !words) return { ok: false, error: 'missing_subject_or_body' };
  if (words > 160) return { ok: false, error: 'body_too_long' };
  return { ok: true, subject: subject.trim(), body: body.trim() };
}

// Meta assigns leadgen ids in live runs, so Facebook leads are matched to their fixture by email.
function fixtureIdFor(sourceId, fixtures = [], email = null) {
  for (const fixture of fixtures) {
    if (fixture.channel === 'form' && sourceId === `form:${fixture.submission_id}`) return fixture.id;
    if (fixture.channel === 'email' && sourceId === `email:${fixture.message_id}`) return fixture.id;
    if (fixture.channel === 'meta_lead' && String(sourceId).startsWith('meta:') && email && fixture.field_data && fixture.field_data.email === email) return fixture.id;
  }
  return null;
}

// Mock mode reads a stored answer instead of calling OpenAI; a missing file behaves like an API failure.
function mockResponse(fileContent, breakLlm) {
  if (breakLlm) return { error: { message: `The model \`${BROKEN_MODEL}\` does not exist (mock)`, httpCode: '404' } };
  if (!fileContent) return { error: { message: 'mock file missing', httpCode: 'mock_missing' } };
  return { choices: [{ message: { content: fileContent } }] };
}

const fs = require('fs');
const entry = $input.first().json.runLog;
const fixtures = JSON.parse(require('fs').readFileSync('/files/sample-data/fixtures.json', 'utf8')).fixtures;
const log = buildRunLog({ ...entry, fixtureId: fixtureIdFor(entry.inquiry.source_id, fixtures, entry.inquiry.email), executionId: $execution.id });
const name = safeId(entry.inquiry.source_id);
fs.mkdirSync('/files/output/run-log', { recursive: true });
fs.writeFileSync('/files/output/run-log/' + Date.now() + '-' + name + '.json', JSON.stringify(log, null, 2), 'utf8');
const reviewFile = '/files/output/review/' + name + '.json';
if (log.draft !== 'none' && fs.existsSync(reviewFile)) {
  const review = JSON.parse(fs.readFileSync(reviewFile, 'utf8'));
  fs.writeFileSync(reviewFile, JSON.stringify({ ...review, status: log.draft, closed_at: log.ts }, null, 2), 'utf8');
}
return [{ json: log }];
